  "tool": "list_operations",
  "operations": [
    {
      "op": "create_layer",
      "category": "layer",
      "description": "Create a layer (no-op with if_exists='skip').",
      "params": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": ""
          },
          "color": {
            "type": "integer",
            "description": "ACI color",
            "minimum": 1,
            "maximum": 255,
            "default": 7
          },
          "linetype": {
            "type": "string",
            "description": "",
            "default": "Continuous"
          },
          "lineweight": {
            "type": "integer",
            "description": "1/100 mm, -3 = default",
            "default": -3
          },
          "if_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "update"
            ],
            "description": "",
            "default": "error"
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "name"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "delete_layer",
      "category": "layer",
      "description": "Delete a layer. Fails if entities are on it unless delete_entities=true.",
