    {
      "op": "array_polar",
      "category": "edit",
      "description": "Polar array about a center: 'count' items (including the original) over 'total_angle'.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Array center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "count": {
            "type": "integer",
            "description": "Total number of items including the original",
            "minimum": 2,
            "maximum": 10000
          },
          "total_angle": {
            "type": "number",
            "description": "Angle to fill (degrees, counter-clockwise)",
            "default": 360.0
          },
          "rotate_items": {
            "type": "boolean",
            "description": "Rotate the copies (else only translate)",
            "default": true
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "center",
          "count"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "array_rect",
      "category": "edit",
      "description": "Rectangular array: copies arranged in rows and columns (the original is cell [0,0]).",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "Entities to operate on — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
