          "rows": {
            "type": "integer",
            "description": "Number of rows",
            "minimum": 1,
            "maximum": 1000
          },
          "cols": {
            "type": "integer",
            "description": "Number of columns",
            "minimum": 1,
            "maximum": 1000
          },
          "row_spacing": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance between rows (Y) (drawing units, or string with unit e.g. '8mm')",
            "default": 0.0
          },
          "col_spacing": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance between columns (X) (drawing units, or string with unit e.g. '8mm')",
            "default": 0.0
          },
          "layout": {
            "type": "string",
            "description": "Layout to work in: 'Model' (default) or a paper-space layout name from read_drawing. New entities go there and filter selectors search it; edits that derive entities from an existing one (copy, offset, trim, fillet) keep them in that entity's layout"
          }
        },
        "required": [
          "target",
          "rows",
          "cols"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "chamfer",
      "category": "edit",
      "description": "AutoCAD CHAMFER of two LINEs with distances d1 (on line1) and d2 (on line2).",
      "params": {
        "type": "object",
        "properties": {
          "line1": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "line2": {
            "description": " — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "d1": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "d2": {
            "type": [
              "number",
              "string"
            ],
            "description": "Defaults to d1 (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
